css.value:
* {
	font-feature-settings: 'clig' off, 'liga' off;
	font-family: Lato;
	font-size: 1rem;
	font-style: normal;
	font-weight: 400;
	line-height: normal;
}

script.inlineScript:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.state.selectedPayload.task.child_kpis.length < 1;
}

css.value:
* {
    color: rgb(var(--Text-text--tertiary, #454D5B));

    /* Display type/header tertiary */
    font-family: Cabin;
    font-size: 1.25rem;
    font-style: normal;
    font-weight: 700;
    line-height: normal;
}

* {
    color: rbg(var(--Text-text--primary, #151920));
    /* Text/md */
    font-family: Lato;
    font-size: 1rem;
    font-style: normal;
    font-weight: 400;
    line-height: normal;
}

* {
    color: rgb(var(--Text-text--primary));
    /* Display type/header tertiary */
    font-family: Cabin;
    font-size: 20px;
    font-style: normal;
    font-weight: 700;
    line-height: normal;
}

script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		modalId: 'confirm_1',
		headerLabel: null,
		showModal: true,
		displayOptions: null,
		bare: null,
		viewportElementId: null,
		viewportRoute: null,
		viewportFields: null,
		viewportParams: null
	};
}
